package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import android.app.*;import android.content.*;import android.content.pm.ProviderInfo;import android.database.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,packageName="de.mika.promptwerk")
@LooperMode(LooperMode.Mode.PAUSED)
public class RuntimeTests {
 MainActivity a;
 public static class Source extends ContentProvider{
 public boolean onCreate(){return true;}public String getType(Uri u){return u.getLastPathSegment().endsWith(".pdf")?"application/pdf":u.getLastPathSegment().endsWith(".txt")?"text/plain":"image/png";}
 public Cursor query(Uri u,String[] p,String s,String[] ar,String sort){MatrixCursor c=new MatrixCursor(new String[]{"_display_name"});c.addRow(new Object[]{u.getLastPathSegment()});return c;}
 public ParcelFileDescriptor openFile(Uri u,String mode)throws FileNotFoundException{try{File f=new File(getContext().getCacheDir(),u.getLastPathSegment());try(OutputStream out=new FileOutputStream(f)){out.write(("content-"+u.getLastPathSegment()).getBytes("UTF-8"));}return ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);}catch(IOException e){throw new FileNotFoundException();}}
 public Uri insert(Uri u,ContentValues v){return null;}public int delete(Uri u,String s,String[] ar){return 0;}public int update(Uri u,ContentValues v,String s,String[] ar){return 0;}}
 @Before public void start(){RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();Source src=new Source();ProviderInfo info=new ProviderInfo();info.authority="source";src.attachInfo(a,info);ShadowContentResolver.registerProviderInternal("source",src);AttachmentProvider files=new AttachmentProvider();ProviderInfo fi=new ProviderInfo();fi.authority=a.getPackageName()+".attachments";files.attachInfo(a,fi);ShadowContentResolver.registerProviderInternal(fi.authority,files);}
 void waitWork()throws Exception{for(int j=0;j<1000;j++){Shadows.shadowOf(Looper.getMainLooper()).idle();if(!a.busy){Shadows.shadowOf(Looper.getMainLooper()).idle();return;}Thread.sleep(10);}fail("Background operation timed out");}
 void pick(String... names)throws Exception{Intent i=new Intent();ClipData clip=null;for(String n:names){Uri u=Uri.parse("content://source/"+n);if(clip==null)clip=ClipData.newRawUri("files",u);else clip.addItem(new ClipData.Item(u));}i.setClipData(clip);a.onActivityResult(20,Activity.RESULT_OK,i);waitWork();if(a.draftFiles.isEmpty()&&ShadowAlertDialog.getLatestAlertDialog()!=null)System.out.println("IMPORT ERROR: "+Shadows.shadowOf(ShadowAlertDialog.getLatestAlertDialog()).getMessage());}
 EditText firstEdit(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int j=0;j<g.getChildCount();j++){EditText e=firstEdit(g.getChildAt(j));if(e!=null)return e;}}return null;}
 @Test public void tenImagesSavedSharedAndBackedUp()throws Exception{
 a.editor.setText("Mein Bildprompt");String[] images=new String[10];for(int j=0;j<10;j++)images[j]="bild"+j+".png";pick(images);assertEquals(10,a.draftFiles.size());pick("elf.png");assertEquals("11th image must not change draft",10,a.draftFiles.size());ShadowAlertDialog.getLatestAlertDialog().dismiss();
 pick("beleg.pdf","notizen.txt");assertEquals(12,a.draftFiles.size());a.copy();assertEquals("Mein Bildprompt",a.editor.getText().toString());assertEquals(12,a.draftFiles.size());a.clear();a.undo();assertEquals("Mein Bildprompt",a.editor.getText().toString());
 a.saveDraft();Shadows.shadowOf(Looper.getMainLooper()).idle();AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();firstEdit(dialog.getWindow().getDecorView()).setText("Bilderprompt");dialog.getButton(DialogInterface.BUTTON_POSITIVE).performClick();assertEquals(12,a.draftFiles.size());assertEquals("Mein Bildprompt",a.editor.getText().toString());MainActivity.Item saved=a.items.get(a.items.size()-1);assertEquals(12,saved.files.size());assertEquals("Bilderprompt",saved.title);
 a.clear();a.insertItem(saved);assertEquals(12,a.draftFiles.size());a.share();Intent chooser=Shadows.shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_CHOOSER,chooser.getAction());Intent send=chooser.getParcelableExtra(Intent.EXTRA_INTENT);assertEquals(Intent.ACTION_SEND_MULTIPLE,send.getAction());assertEquals("Mein Bildprompt",send.getStringExtra(Intent.EXTRA_TEXT));assertEquals(12,send.getParcelableArrayListExtra(Intent.EXTRA_STREAM).size());assertEquals(12,send.getClipData().getItemCount());assertTrue((send.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0);assertEquals(12,a.draftFiles.size());assertEquals("Mein Bildprompt",a.editor.getText().toString());a.clear();a.undo();assertEquals(12,a.draftFiles.size());
 File zip=new File(a.getCacheDir(),"roundtrip.zip");org.json.JSONObject m=new org.json.JSONObject();m.put("format","promptwerk");m.put("version",2);m.put("items",a.data());m.put("draft","gesichert");m.put("draftFiles",MainActivity.attJson(a.draftFiles));a.editor.setText("gesichert");Intent exportResult=new Intent();exportResult.setData(Uri.fromFile(zip));a.onActivityResult(10,Activity.RESULT_OK,exportResult);waitWork();assertTrue(zip.length()>0);
 a.items.clear();a.clear();for(MainActivity.Att at:saved.files)a.file(at).delete();a.importBackup(Uri.fromFile(zip));Shadows.shadowOf(Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();waitWork();assertEquals(1,a.items.stream().filter(it->it.title.equals("Bilderprompt")).count());ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals("gesichert",a.editor.getText().toString());assertEquals(12,a.draftFiles.size());for(MainActivity.Att at:a.draftFiles)assertTrue(a.file(at).isFile());MainActivity reopened=Robolectric.buildActivity(MainActivity.class).setup().get();assertEquals(12,reopened.draftFiles.size());assertEquals("gesichert",reopened.editor.getText().toString());assertEquals(12,reopened.items.stream().filter(it->it.title.equals("Bilderprompt")).findFirst().get().files.size());
 }
 @Test public void providerIsReadOnlyAndChecksPaths()throws Exception{pick("lesbar.txt");MainActivity.Att at=a.draftFiles.get(0);Uri u=a.uri(at);try(InputStream in=a.getContentResolver().openInputStream(u)){assertEquals("content-lesbar.txt",new String(in.readAllBytes(),"UTF-8"));}try(Cursor c=a.getContentResolver().query(u,null,null,null,null)){assertTrue(c.moveToFirst());assertEquals("lesbar.txt",c.getString(0));}try{a.getContentResolver().openOutputStream(u,"w");fail("provider must reject writes");}catch(FileNotFoundException expected){}try{a.getContentResolver().openInputStream(Uri.parse("content://"+a.getPackageName()+".attachments/../secret"));fail("path must be rejected");}catch(FileNotFoundException expected){}}
 @Test public void legacyJsonAndCancelledSaveKeepData()throws Exception{a.editor.setText("nicht verlieren");a.saveDraft();Shadows.shadowOf(Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-2).performClick();assertEquals("nicht verlieren",a.editor.getText().toString());org.json.JSONObject old=new org.json.JSONObject("{\"title\":\"Alt\",\"text\":\"Text\",\"type\":\"prompt\"}");assertTrue(a.parse(old).files.isEmpty());a.clear();a.clear();a.undo();assertEquals("nicht verlieren",a.editor.getText().toString());}
 @Test public void invalidZipCannotWriteOutsideStagingOrChangeLibrary()throws Exception{int before=a.items.size();File zip=new File(a.getCacheDir(),"invalid.zip");try(java.util.zip.ZipOutputStream z=new java.util.zip.ZipOutputStream(new FileOutputStream(zip))){z.putNextEntry(new java.util.zip.ZipEntry("../escape.txt"));z.write(new byte[]{1});z.closeEntry();}try{a.importBackup(Uri.fromFile(zip));fail("must reject traversal");}catch(IOException expected){}assertEquals(before,a.items.size());assertFalse(new File(a.getCacheDir(),"escape.txt").exists());}
 Button findButton(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=findButton(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 @Test public void archiveKeepsFilesEditableAcrossRestartAndBackup()throws Exception{
 pick("archiv.pdf");MainActivity.Item item=new MainActivity.Item("Später weiter","Noch eine Idee","prompt");item.files.addAll(a.draftFiles);item.star=true;a.items.add(item);a.persist();a.render();
 a.setArchived(item,true);assertTrue(item.archived);assertNull(Shadows.shadowOf(a).getNextStartedActivityForResult());
 a.showOverview();assertTrue(a.overviewDialog.isShowing());assertTrue(a.overviewRows.getChildCount()>0);
 a.edit(item);Shadows.shadowOf(Looper.getMainLooper()).idle();a.entryWindow.title.setText("Später ergänzt");a.entryWindow.save();assertTrue(item.archived);assertEquals("Später ergänzt",item.title);
 MainActivity reopened=Robolectric.buildActivity(MainActivity.class).setup().get();MainActivity.Item stored=reopened.items.stream().filter(it->it.title.equals("Später ergänzt")).findFirst().get();assertTrue(stored.archived);assertTrue(stored.star);assertTrue(reopened.file(stored.files.get(0)).isFile());
 // Export through the real document result handler includes archive metadata and bytes.
 File zip=new File(a.getCacheDir(),"archive.zip");a.onActivityResult(10,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(zip)));waitWork();a.items.clear();a.persist();a.clear();a.file(item.files.get(0)).delete();a.importBackup(Uri.fromFile(zip));Shadows.shadowOf(Looper.getMainLooper()).idle();ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();waitWork();MainActivity.Item restored=a.items.stream().filter(it->it.title.equals("Später ergänzt")).findFirst().get();assertTrue(restored.archived);assertTrue(a.file(restored.files.get(0)).isFile());
 a.setArchived(restored,false);assertFalse(restored.archived);assertNotNull(findButton(a.rows,"Erledigt"));
 assertFalse(a.parse(new org.json.JSONObject("{\"title\":\"Alt\",\"text\":\"Text\",\"type\":\"prompt\"}")).archived);
 }
 @Test @GraphicsMode(GraphicsMode.Mode.NATIVE) public void consistentButtonsAndInfoCanReopen()throws Exception{
 a.editor.setText("Eine Idee, die bleiben darf.");a.showDraft();String before=a.prefs.getString("items","");
 View content=a.findViewById(android.R.id.content);content.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));content.layout(0,0,360,800);
 assertEquals(a.dp(38),a.attachButton.getHeight());assertEquals(a.dp(38),findButton(a.root,"Kopieren").getHeight());
 android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(360,800,android.graphics.Bitmap.Config.ARGB_8888);content.draw(new android.graphics.Canvas(bitmap));try(OutputStream out=new FileOutputStream("tests/Promptwerk-2.1-Vorschau.png")){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}
 for(int i=0;i<3;i++){a.showInfo();assertNotNull(a.fox);if(i==0){View decor=a.infoDialog.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY));decor.layout(0,0,360,760);android.graphics.Bitmap info=android.graphics.Bitmap.createBitmap(360,760,android.graphics.Bitmap.Config.ARGB_8888);decor.draw(new android.graphics.Canvas(info));try(OutputStream out=new FileOutputStream("tests/Promptwerk-2.1-Impressum.png")){info.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}findButton(a.infoDialog.getWindow().getDecorView(),"Animation pausieren").performClick();assertNotNull(findButton(a.infoDialog.getWindow().getDecorView(),"Animation abspielen"));a.onPause();a.onResume();a.infoDialog.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();assertNull(a.fox);assertEquals(before,a.prefs.getString("items",""));assertEquals("Eine Idee, die bleiben darf.",a.editor.getText().toString());}
 }

}
